/* @lc app=leetcode id=1857 lang=kotlin */ class Solution { fun largestPathValue(colors: String, edges: Array<IntArray>): Int = colors.length.let { n -> edges.groupBy({ it[0] }, { it[1] }).let { g -> IntArray(n).also { d -> edges.forEach { d[it[1]]++ } }.let { d -> Array(n) { IntArray(26) }.let { dp -> generateSequence((0 until n).filter { d[it] == 0 }) { f -> f.flatMap { u -> (++dp[u][colors[u] - 'a']).let { g[u].orEmpty().filter { v -> (0 until 26).forEach { c -> dp[v][c] = maxOf(dp[v][c], dp[u][c]) }.let { --d[v] == 0 } } } }.takeIf { it.isNotEmpty() } }.flatten().toList().let { order -> if (order.size < n) -1 else order.maxOf { u -> dp[u].max() } } } } } } }